{"content":""""Loader for versioned local maintainer profiles; see README.md."""

import importlib


def load_config(text: str) -> dict:
    settings = {}
    plugin = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        key, _, expression = line.partition("=")
        key = key.strip()
        value = eval(expression)
        if key == "plugin":
            module = importlib.import_module(value)
            plugin = module.Transform()
        else:
            settings[key] = value
    return {"settings": settings, "plugin": plugin}
